from sst_h import *
META = meta(3)
hm, gm = map_pair([('A','Dandi',"The place where Gandhiji broke the salt law in March 1930."),('B','Kheda',"The place where Gandhiji launched a Satyagraha in 1917 in support of peasants affected by crop failure.")],
  [("The dam built on the river Narmada in Gujarat.", 'Sardar Sarovar'), ("The dam on the river Krishna in Telangana/Andhra Pradesh, one of the largest masonry dams.", 'Nagarjuna Sagar'), ("The dam on the river Tungabhadra in Karnataka.", 'Tungabhadra'), ("The dam on the river Chenab in Jammu & Kashmir.", 'Salal')])
HIS = sec("SECTION A — HISTORY", "20 marks", [
 ar("Giuseppe Mazzini is regarded as a prophet of Italian nationalism.", "He founded secret societies 'Young Italy' and 'Young Europe' to spread the ideal of a unified republic.", 'a', "Both true; R explains A."),
 stmt("Read the statements and choose the correct option.", "The Rowlatt Act of 1919 gave the government enormous powers to repress political activities.", "It allowed detention of political prisoners without trial for two years.", 'a', "Both correct."),
 match("Match Column I with Column II.", [("1. Jallianwala Bagh","a. April 1919, Amritsar"),("2. Poona Pact","b. 1932 – reserved seats for depressed classes"),("3. Dandi March","c. 1930 – Salt law")], ["(a) 1-a, 2-b, 3-c","(b) 1-b, 2-a, 3-c","(c) 1-c, 2-b, 3-a","(d) 1-a, 2-c, 3-b"], 'a', "All three matches are correct."),
 mcq("Which of the following statements about the Age of Industrialisation is INCORRECT?", ["Before factories, merchants moved to the countryside under proto-industrialisation.", "The Spinning Jenny was invented by James Hargreaves.", "Jobbers were appointed by industrialists to get new recruits.", "Indian cotton textiles lost their European markets owing to the East India Company's monopoly being removed from India."], 'd', "Indian textiles lost European markets because of competition from British machine-made goods and tariffs; the statement is a distortion."),
 sa("What was the impact of the First World War on the Indian industries? Mention any two points.", 2, "(1) British mills were busy producing war supplies, Indian mills got a vast home market. (1) Indian factories were called upon to supply war needs (jute bags, cloth for army uniforms, tents, leather boots); new factories were set up and workers employed."),
 sa("'Print culture created conditions for the French Revolution.' Support the statement with three points.", 3, "(1) Print popularised Enlightenment ideas. (1) Created a new culture of dialogue and debate. (1) Caricatures and tracts mocked the monarchy by the 1780s."),
 OR(sa("Explain the effects of the Non-Cooperation Movement on the economic front.", 5, "(1) Foreign goods were boycotted, liquor shops picketed, foreign cloth burnt. (1) Import of foreign cloth halved between 1921 and 1922; value dropped from Rs 102 crore to Rs 57 crore. (1) Indian textile mills and handlooms prospered. (1) Merchants refused to trade in foreign goods. (1) Movement slowed in cities due to costly khadi and lack of alternative institutions."),
    sa("Describe how different social groups participated in the Civil Disobedience Movement.", 5, "(1) Rich peasants (Patidars, Jats) – campaign against high revenue. (1) Poor peasants – wanted unpaid rent waived. (1) Business classes – FICCI, opposed colonial restrictions. (1) Industrial workers of Nagpur – boycott. (1) Women – participated in large numbers in salt march and picketing.")),
 case_n("Read the source and answer the questions.<br><i>Gandhiji's Satyagraha idea emphasised the power of truth and the need to search for truth. It suggested that if the cause was true, if the struggle was against injustice, then physical force was not necessary to fight the oppressor. Without seeking vengeance or being aggressive, a satyagrahi could win the battle through non-violence.</i>",
  [sub("What does Satyagraha emphasise?", 1, "The power of truth and non-violent resistance."), sub("Name the first Satyagraha movement organised by Gandhiji in India.", 1, "Champaran (Bihar), 1917 (indigo planters)."), sub("Explain how the satyagraha method differed from other forms of struggle.", 2, "(1) It did not use physical force or violence; it relied on moral power and truth. (1) It appealed to the conscience of the oppressor and sought to convert rather than defeat him.")]),
 hm])
GEO = sec("SECTION B — GEOGRAPHY", "20 marks", [
 ar("Multi-purpose river projects are called 'temples of modern India' by Nehru.", "They integrate the conservation and management of water with flood control, irrigation, power generation and fisheries.", 'a', "Both true; R explains A."),
 stmt("Read the statements and choose the correct option.", "Soil erosion can be checked by contour ploughing and terrace farming.", "Shelter belts of trees in desert regions help in stabilising sand dunes.", 'a', "Both correct."),
 match("Match the following.", [("1. Alluvial soil","a. Rich in potash, lime and phosphoric acid"),("2. Black soil","b. Made of extremely fine clayey material"),("3. Laterite soil","c. Develops in high temperature and heavy rainfall")], ["(a) 1-a, 2-b, 3-c","(b) 1-b, 2-a, 3-c","(c) 1-c, 2-b, 3-a","(d) 1-a, 2-c, 3-b"], 'a', "Alluvial – potash; black – fine clay; laterite – heavy rainfall."),
 mcq("Which of the following statements about conventional energy is INCORRECT?", ["Coal is the most abundantly available fossil fuel in India.", "Petroleum is found in anticlinal traps.", "Natural gas is used as a fuel and as an industrial raw material.", "Thermal power uses renewable resources and does not release pollutants."], 'd', "Thermal power uses coal/oil/gas and pollutes."),
 mcq("Which one of the following is a rabi crop?", ["Jowar", "Bajra", "Wheat", "Ragi"], 'c', "Wheat is a rabi crop."),
 mcq("Which of the following is the major cotton-producing state of India?", ["Gujarat", "Kerala", "Assam", "Odisha"], 'a', "Gujarat is a leading cotton producer (with Maharashtra)."),
 mcq("Which one of the following is a feature of the Eastern Coastal Plain?", ["Deltas of Mahanadi, Godavari, Krishna and Kaveri", "Fertile black soil", "Desert", "Lava plateau"], 'a', "East coast has fertile deltas."),
 OR(sa("Why is it necessary to conserve minerals? Give two reasons.", 2, "(1) Minerals are exhaustible and take millions of years to form; the rate of replenishment is negligible. (1) Concentrated mineral resources are limited; need to preserve for the future."),
    sa("Differentiate between khadar and bangar soil.", 2, "(1) Khadar – new alluvium, finer, more fertile, found in flood plains. (1) Bangar – old alluvium, has higher concentration of kanker nodules, less fertile, found away from floodplains.")),
 sa("Explain three advantages of multi-purpose river projects.", 3, "(1) Irrigation. (1) Hydroelectric power. (1) Flood control, inland navigation, fish breeding, water supply / tourism."),
 OR(sa("Describe the major problems of agriculture in India and suggest remedial measures.", 5, "(3) Dependence on monsoon, fragmented holdings, lack of capital, soil degradation, disguised unemployment, poor marketing. (2) Land reforms, minimum support price, Kisan Credit Cards, crop insurance, Grameen banks, weather bulletins."),
    sa("What are the conventional sources of energy? Describe their significance and concerns.", 5, "(2) Coal, petroleum, natural gas, electricity (thermal/hydel). (2) Significance: industry, transport, domestic use, power. (1) Concerns: fossil fuels deplete and pollute; need for renewable sources.")),
 gm])
POL = sec("SECTION C — POLITICAL SCIENCE", "20 marks", [
 ar("Belgium has a power-sharing arrangement unlike Sri Lanka.", "Belgium's Constitution gives equal representation to Dutch- and French-speaking ministers in the central government.", 'a', "Both true; R explains the Belgian model."),
 stmt("Read the statements and choose the correct option.", "In a federal system, the central government can order the state government to do something.", "Power is divided among different levels of government with constitutional guarantees.", 'd', "Statement I is false in a federal system; II is true. Hence only II is correct — option (d)."),
 mcq("Which of the following is NOT a form of power sharing?", ["Among different organs of government", "Between governments at different levels", "Among social groups", "Concentrating power at the centre alone"], 'd', "Concentration is the opposite of power sharing."),
 mcq("Which of the following statements about the Panchayati Raj is INCORRECT?", ["Gram Panchayat is the lowest tier.", "A third of seats are reserved for women in local bodies.", "Elections to local bodies are held regularly.", "Local governments are directly elected by the State governments."], 'd', "Members are elected directly by the people."),
 mcq("Which Article or provision made Hindi the official language of the Union?", ["Article 343", "Article 14", "Article 21", "Article 370"], 'a', "Article 343 (Hindi in Devanagari script)."),
 mcq("Which is NOT a feature of a secular state?", ["Freedom to practise any religion", "No official religion", "Discrimination on grounds of religion", "Equal treatment of all faiths"], 'c', "A secular state does not discriminate."),
 sa("Why is power sharing desirable? State any two reasons.", 2, "(1) Prudential – reduces the possibility of conflict between social groups. (1) Moral – power sharing is the very spirit of democracy; ensures legitimacy of government."),
 OR(sa("Explain any three features of federalism.", 3, "Any three: two or more levels of government; each with own jurisdiction; Constitution specifies jurisdictions; fundamental provisions can't be changed unilaterally; courts act as umpires; sources of revenue specified; dual objectives of unity and autonomy."),
    sa("Explain any three provisions made in the Constitution of India to protect linguistic diversity.", 3, "(1) No national language; Hindi is the official language. (1) 22 languages in the Eighth Schedule; official work in English also. (1) States have their own official languages; Centre uses the language of the states while communicating.")),
 OR(sa("How has the decentralisation of power strengthened democracy in India? Explain.", 5, "(1) 73rd and 74th Amendments (1992) made third-tier democracy more powerful. (1) Regular elections to local bodies mandatory. (1) Reservation of one-third seats for women, SC, ST, OBC. (1) State Election Commission created. (1) Local issues solved locally, more participation, but financial problems remain."),
    sa("Explain the role of the Election Commission and the challenges to Indian democracy in elections.", 5, "(2) Independent body conducts and supervises elections. (2) Challenges: money and muscle power, criminalisation, dynastic politics. (1) Reforms like affidavits, disclosure.")),
 case_n("Read the source and answer the questions.<br><i>The Constitution has provided for the division of powers between the Union and the States in three lists: Union List, State List and Concurrent List. Residuary subjects, those not mentioned in any list, are with the Union.</i>",
  [sub("How many lists are mentioned in the passage?", 1, "Three."), sub("Who has the power to legislate on residuary subjects?", 1, "The Union Government."), sub("Give two subjects of the State List and explain why states are given these subjects.", 2, "(1) Police, trade, commerce, agriculture, irrigation (any two). (1) Because they are of local and regional importance.")])])
ECO = sec("SECTION D — ECONOMICS", "20 marks", [
 ar("Per capita income is a better measure than total income to compare development.", "It reflects the average income of each person in a country.", 'a', "Both true; R explains A."),
 stmt("Read the statements.", "The Human Development Index is published by UNDP.", "Life expectancy, literacy and per capita income are included in HDI.", 'a', "Both correct."),
 mcq("Which of the following is NOT a feature of the tertiary sector?", ["Produces services", "Helps primary and secondary sectors", "Produces goods from natural products", "Transport and banking are included"], 'c', "Goods production belongs to primary/secondary sectors."),
 sa("What is disguised unemployment? Give an example.", 2, "(1) A situation where more people are employed than needed; removal of some does not affect output. (1) Example: five members work on a small farm needing only three."),
 OR(sa("Explain three reasons for the growing importance of the tertiary sector.", 3, "(1) Basic services like hospitals, education, transport needed. (1) Development of agriculture and industry creates demand for trade, transport. (1) Rise in income leads to demand for tourism, shopping, private services; new services based on IT."),
    sa("Explain three features of the organised sector.", 3, "(1) Regular terms of employment, registered with the government. (1) Workers enjoy security of employment, paid leave, pension, gratuity. (1) Follow rules and regulations of the Factories Act etc.")),
 sa("Explain three terms of credit that borrowers face while taking loans.", 3, "(1) Interest rate. (1) Collateral. (1) Documentation requirements and mode of repayment."),
 OR(sa("What is MGNREGA 2005? Explain how it addresses unemployment.", 5, "(1) Guarantees 100 days of employment in a year to rural households. (1) If government fails, it gives unemployment allowance. (1) Work related to the development of land/water conservation. (1) One-third of jobs reserved for women. (1) Creates assets, reduces migration."),
    sa("Describe how MNCs have spread their production across countries and the role of foreign trade in integrating markets.", 5, "(2) MNCs set up offices and factories where cheap labour and raw material are available, partnerships with local companies, buying local firms. (2) Foreign trade connects markets; goods move from one market to another. (1) Prices of the same goods tend to be similar.")),
 case_n("Read the source and answer.<br><i>The HDI ranking of India in 2019 was 131 out of 189 countries. Kerala has a lower infant mortality rate and higher literacy than Haryana, although Haryana's per capita income is higher.</i>",
  [sub("Which organisation publishes HDI?", 1, "UNDP."), sub("Which state has a lower infant mortality rate according to the passage?", 1, "Kerala."), sub("Explain how this shows that income alone is not enough to measure development.", 2, "(1) Haryana has higher income but Kerala does better in health and education. (1) Development includes health, education and quality of life, not only income.")])])
SECTIONS = [HIS, GEO, POL, ECO]
